head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > maxYear]<br/>Calendar 컴포넌트에서 선택할 수 있는 최대 연도를 설정합니다.",
    "validation" : [
        "Number 값으로 연도 범위의 상한값을 4자리 정수로 설정합니다.",
        "값을 설정하지 않으면 config.xml 의 /WebSquare/calendar/maxYear/@value 설정값이 적용되며, 기본 배포 값은 '2030' 입니다.",
        "연도 SelectBox 에 minYear 속성값부터 maxYear 속성값까지의 연도가 표시됩니다.",
        "maxYear 속성값의 12월에서 다음 달/다음 연도 이동이 차단됩니다.",
        "gotoCalendar() 메소드로 maxYear 를 초과하는 연도를 설정하면 maxYear 로 적용됩니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        maxYear : con_maxYear.getValue(),
        minYear : con_minYear.getValue()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);

    // maxYear 의 12월로 초기 이동 (다음월 이동 차단 검증 편의)
    let maxY = parseInt(target1.options.maxYear);
    if (!isNaN(maxY)) {
        target1.gotoCalendar(maxY + "1201");
    }
}



// validation: gotoCalendar() 메소드로 maxYear 를 초과하는 연도를 설정하면 maxYear 로 적용됨
scwin.btn_gotoOverMaxYear_onclick = function (e) {
    let maxY = parseInt(target1.options.maxYear);
    if (isNaN(maxY)) {
        wf_body_bottom.getObj("scwin").setReturnValue("[gotoCalendar 초과 시도] maxYear 가 숫자가 아님");
        return;
    }

    // maxYear + 75년의 임의 초과값
    let overYear = (maxY + 75);
    let dateStr = overYear + "0101";
    target1.gotoCalendar(dateStr);

    let returnValue = target1.getValue();
    let returnedYear = returnValue.substring(0, 4);
    let clamped = (parseInt(returnedYear) === maxY);

    wf_body_bottom.getObj("scwin").setReturnValue("[gotoCalendar 초과 시도 결과] 요청='" + dateStr + "', getValue()='" + returnValue + "', 반환된 연도=" + returnedYear + " (maxYear=" + maxY + ") → " + (clamped ? "maxYear 로 클램핑됨" : "클램핑되지 않음"));
};
